// machines/plaits: VA's variable saw sample loop (engines/va.c, saw_render), hand-written SISD kernel.
// Generated by lib/gen_va_kernel.py; do not edit by hand.
//
// saw_kernel(Saw *s, const float *k, float *out, int size):
//   s = the saw (phase_, next_sample_, previous_pw_, high_, then the three interpolators' values frequency_, pw_,
//   waveshape_); k[0..2] = the interpolators' increments. Writes `size` samples to out and the state back (the
//   values are the interpolators' commits), bit-identical to selcc's code of the C loop (-DPL_VA_C): the same
//   operations with the same operands in the same order (tests/plaits/test_va_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, M6, L0, L1, L4 pushed through R0, M6 = 1 and L0 = L1 = L4 = 0 set here). No SIMD, no DO loop.
// Registers in the loop: R15 phase, R13 next_sample, R12 this_sample, R11 high_, R10 frequency, R9 pw; I1 = s,
// I4 = k, I0 = out; the other per-sample values live in frame slots above I7.
//
// ABI: as the other kernels (lib/wavetable_sm.s): relies on M5 = 0 and M7 = -1, sets M6 = 1 itself; DAG registers
// are pushed through R0 and restored by loads through I7. Assembled under .COMPRESS (the assembler leaves the
// instructions of a DO loop in their 48-bit forms, as the PRM requires for a loop's last 11): smaller hot code.

.SECTION/PM seg_pmco;
.GLOBAL saw_kernel.;
.COMPRESS;

saw_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I7=MODIFY (I7,-14)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(1, I6);                                     // size
    DM(12, I7) = R0;
    R15 = DM(0, I1);                                    // phase_
    R13 = DM(1, I1);                                    // next_sample_
    R2 = DM(2, I1);                                     // previous_pw_
    DM(11, I7) = R2;
    R11 = DM(3, I1);                                    // high_
    R1 = 0x3F800000;
    R2 = 0x3E4CCCCD;
    F2 = F1 + F2;                                       // 1.0f + kVariableSawNotchDepth
    DM(14, I7) = R2;
    R3 = 0x40000000;
    F4 = RECIPS F2;
    F5 = F2 * F4;
    F5 = F3 - F5;
    F4 = F4 * F5;
    F5 = F2 * F4;
    F5 = F3 - F5;
    F4 = F4 * F5;
    DM(13, I7) = R4;
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _swk_done;
_swk_loop:
    R12 = PASS R13;                                     // this_sample = next_sample
    R13 = 0;                                            // next_sample = 0.0f
    R0 = DM(4, I1);
    R1 = DM(0, I4);
    F10 = F0 + F1;                                      // frequency = fm.Next()
    DM(4, I1) = R10;
    R0 = DM(5, I1);
    R1 = DM(1, I4);
    F9 = F0 + F1;                                       // pw
    DM(5, I1) = R9;
    R0 = DM(6, I1);
    R1 = DM(2, I4);
    F0 = F0 + F1;                                       // waveshape = triangle_amount
    DM(6, I1) = R0;
    DM(9, I7) = R0;
    R1 = 0x3F800000;
    F1 = F1 - F0;                                       // notch_amount = 1.0f - waveshape
    DM(10, I7) = R1;
    R0 = 0x3F800000;
    R3 = 0x40000000;
    R7 = 0x40000000;
    F4 = F0 - F9;                                       // 1.0f - pw
    F1 = RECIPS F9;
    F5 = RECIPS F4;
    F2 = F9 * F1;                                       // slope_up, slope_down: selcc divisions
    F6 = F4 * F5;
    F2 = F3 - F2;
    F6 = F7 - F6;
    F1 = F1 * F2;
    F5 = F5 * F6;
    F2 = F9 * F1;
    F6 = F4 * F5;
    F2 = F3 - F2;
    F6 = F7 - F6;
    F1 = F1 * F2;
    F5 = F5 * F6;
    F3 = F0 * F1;
    F7 = F0 * F5;
    F2 = F9 * F3;
    F6 = F4 * F7;
    F2 = F0 - F2;
    F6 = F0 - F6;
    F2 = F2 * F1;
    F6 = F6 * F5;
    F3 = F3 + F2;
    F7 = F7 + F6;
    DM(7, I7) = R3;                                     // slope_up
    DM(8, I7) = R7;                                     // slope_down
    F15 = F15 + F10;                                    // phase_ += frequency
    R2 = 0;
    COMP(R11, R2);                                      // !high_ && phase_ >= pw
    IF NE JUMP _swk_else;
    COMP(F15, F9);
    IF LT JUMP _swk_else;
    R6 = DM(7, I7);
    R7 = DM(8, I7);
    F6 = F6 + F7;                                       // triangle_step
    F6 = F6 * F10;
    R7 = DM(9, I7);
    F6 = F6 * F7;
    R1 = 0x3E4CCCCD;
    R0 = 0x3F800000;
    F1 = F1 + F0;                                       // kVariableSawNotchDepth + 1.0f - pw
    F1 = F1 - F9;
    R0 = DM(10, I7);
    F8 = F1 * F0;                                       // notch
    R0 = DM(11, I7);
    F0 = F0 - F9;                                       // previous_pw_ - pw + frequency
    F0 = F0 + F10;
    F1 = F15 - F9;                                      // phase_ - pw
    R4 = 0x40000000;
    R14 = PASS R8;                                      // notch (the division uses R3-R5)
    F3 = RECIPS F0;
    F5 = F0 * F3;                                       // t
    F5 = F4 - F5;
    F3 = F3 * F5;
    F5 = F0 * F3;
    F5 = F4 - F5;
    F3 = F3 * F5;
    F4 = F1 * F3;
    F5 = F0 * F4;
    F5 = F1 - F5;
    F5 = F5 * F3;
    F2 = F4 + F5;
    R8 = PASS R14;
    R0 = 0x3F000000;
    F0 = F0 * F2;                                       // ThisBlepSample(t)
    F0 = F0 * F2;
    F0 = F8 * F0;
    F12 = F12 + F0;
    R1 = 0x3F800000;
    F3 = F1 - F2;                                       // 1 - t
    R0 = 0xBF000000;
    F0 = F0 * F3;                                       // NextBlepSample(t)
    F0 = F0 * F3;
    F0 = F8 * F0;
    F13 = F13 + F0;
    R0 = 0x3F000000;
    F4 = F0 * F3;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // ThisIntegratedBlepSample(t)
    F12 = F12 - F1;
    R0 = 0x3F000000;
    F4 = F0 * F2;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // NextIntegratedBlepSample(t)
    F13 = F13 - F1;
    R11 = 1;                                            // high_ = 1
    JUMP _swk_naive;
_swk_else:
    R0 = 0x3F800000;
    COMP(F15, F0);                                      // else if (phase_ >= 1.0f)
    IF LT JUMP _swk_naive;
    F15 = F15 - F0;
    R6 = DM(7, I7);
    R7 = DM(8, I7);
    F6 = F6 + F7;                                       // triangle_step
    F6 = F6 * F10;
    R7 = DM(9, I7);
    F6 = F6 * F7;
    R1 = 0x3E4CCCCD;
    R0 = 0x3F800000;
    F1 = F1 + F0;                                       // (kVariableSawNotchDepth + 1.0f) * notch_amount
    R0 = DM(10, I7);
    F14 = F1 * F0;                                      // notch
    R4 = 0x40000000;
    F3 = RECIPS F10;
    F5 = F10 * F3;                                      // t = phase_ / frequency
    F5 = F4 - F5;
    F3 = F3 * F5;
    F5 = F10 * F3;
    F5 = F4 - F5;
    F3 = F3 * F5;
    F4 = F15 * F3;
    F5 = F10 * F4;
    F5 = F15 - F5;
    F5 = F5 * F3;
    F2 = F4 + F5;
    R8 = PASS R14;
    R0 = 0x3F000000;
    F0 = F0 * F2;                                       // ThisBlepSample(t)
    F0 = F0 * F2;
    F0 = F8 * F0;
    F12 = F12 - F0;
    R1 = 0x3F800000;
    F3 = F1 - F2;                                       // 1 - t
    R0 = 0xBF000000;
    F0 = F0 * F3;                                       // NextBlepSample(t)
    F0 = F0 * F3;
    F0 = F8 * F0;
    F13 = F13 - F0;
    R0 = 0x3F000000;
    F4 = F0 * F3;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // ThisIntegratedBlepSample(t)
    F12 = F12 + F1;
    R0 = 0x3F000000;
    F4 = F0 * F2;                                       // t1
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R8 = 0x3E400000;
    F4 = F8 - F4;                                       // 0.1875 - t1
    R0 = 0x3FC00000;
    F5 = F0 * F5;                                       // 1.5 t2
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F6 * F1;                                       // NextIntegratedBlepSample(t)
    F13 = F13 + F1;
    R11 = 0;                                            // high_ = 0
_swk_naive:
    R1 = 0x3E4CCCCD;
    R0 = 0x3F800000;
    F1 = F0 + F1;                                       // 1.0f + kVariableSawNotchDepth
    COMP(F15, F9);                                      // notch_saw = phase < pw ? phase : ..
    IF LT R1 = R15 OR R15;
    R2 = DM(7, I7);
    F2 = F15 * F2;                                      // phase * slope_up
    F3 = F15 - F9;
    R4 = DM(8, I7);
    F3 = F3 * F4;
    F3 = F0 - F3;                                       // 1.0f - (phase - pw) * slope_down
    COMP(F15, F9);                                      // triangle = phase < pw ? ..
    IF LT R3 = R2 OR R2;
    R4 = DM(10, I7);
    F1 = F1 * F4;                                       // notch_saw * notch_amount
    R4 = DM(9, I7);
    F3 = F3 * F4;                                       // triangle * triangle_amount
    F1 = F1 + F3;
    F13 = F13 + F1;                                     // next_sample += saw_naive(..)
    DM(11, I7) = R9;                                    // previous_pw_ = pw
    R0 = 0x40000000;
    F0 = F0 * F12;                                      // (2.0f * this_sample - 1.0f) / (1.0f + kVariableSawNotchDepth)
    R1 = 0x3F800000;
    F5 = F0 - F1;                                       // n
    R4 = DM(13, I7);
    R2 = DM(14, I7);
    F0 = F5 * F4;                                       // selcc division: w = n y
    F1 = F2 * F0;                                       // t = d w
    F1 = F5 - F1;                                       // t = n - t
    F1 = F1 * F4;                                       // t = t y
    F0 = F0 + F1;
    DM(I0, M6) = R0;
    R0 = DM(12, I7);
    R1 = 1;
    R0 = R0 - R1;
    DM(12, I7) = R0;
    IF NE JUMP _swk_loop;
_swk_done:
    DM(0, I1) = R15;
    DM(1, I1) = R13;
    R0 = DM(11, I7);
    DM(2, I1) = R0;
    DM(3, I1) = R11;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,14)(NW);
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
